module beacon_connectivity (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [2:0] num_beacons,\n    input wire [63:0] adj_matrix,\n    output reg [3:0] result,\n    output reg done\n);\n\n// Parameters\nlocalparam MAX_N = 8;\n\n// State definitions\nlocalparam [2:0] IDLE      = 3'd0;\nlocalparam [2:0] INIT      = 3'd1;\nlocalparam [2:0] K_LOOP    = 3'd2;\nlocalparam [2:0] I_LOOP    = 3'd3;\nlocalparam [2:0] COUNT_INIT = 3'd4;\nlocalparam [2:0] COUNT_LOOP = 3'd5;\n\n// Registers\nreg [2:0] state;\nreg [2:0] i, k;\nreg [7:0] reach [0:7];\nreg [7:0] visited;\nreg [3:0] count;\nreg [7:0] adj_row_i;\n\n// Combinational adjacency row selection\nalways @(*) begin\n    case(i)\n        3'd0: adj_row_i = adj_matrix[7:0];\n        3'd1: adj_row_i = adj_matrix[15:8];\n        3'd2: adj_row_i = adj_matrix[23:16];\n        3'd3: adj_row_i = adj_matrix[31:24];\n        3'd4: adj_row_i = adj_matrix[39:32];\n        3'd5: adj_row_i = adj_matrix[47:40];\n        3'd6: adj_row_i = adj_matrix[55:48];\n        3'd7: adj_row_i = adj_matrix[63:56];\n        default: adj_row_i = 8'd0;\n    endcase\nend\n\n// Sequential logic\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        result <= 4'd0;\n        i <= 3'd0;\n        k <= 3'd0;\n        visited <= 8'd0;\n        count <= 4'd0;\n        reach[0] <= 8'd0;\n        reach[1] <= 8'd0;\n        reach[2] <= 8'd0;\n        reach[3] <= 8'd0;\n        reach[4] <= 8'd0;\n        reach[5] <= 8'd0;\n        reach[6] <= 8'd0;\n        reach[7] <= 8'd0;\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    state <= INIT;\n                    i <= 3'd0;\n                end\n            end\n            INIT: begin\n                if (i < 3'd7) begin\n                    if (i < num_beacons) begin\n                        reach[i] <= adj_row_i | (8'd1 << i);\n                    end else begin\n                        reach[i] <= 8'd0;\n                    end\n                    i <= i + 3'd1;\n                end else begin\n                    k <= 3'd0;\n                    state <= K_LOOP;\n                end\n            end\n            K_LOOP: begin\n                if (k < num_beacons) begin\n                    i <= 3'd0;\n                    state <= I_LOOP;\n                end else begin\n                    state <= COUNT_INIT;\n                end\n            end\n            I_LOOP: begin\n                if (i < num_beacons) begin\n                    if (i != k && reach[i][k]) begin\n                        reach[i] <= reach[i] | reach[k];\n                    end\n                    i <= i + 3'd1;\n                end\n                if (i >= num_beacons - 3'd1) begin\n                    k <= k + 3'd1;\n                    state <= K_LOOP;\n                end\n            end\n            COUNT_INIT: begin\n                visited <= 8'd0;\n                count <= 4'd0;\n                i <= 3'd0;\n                state <= COUNT_LOOP;\n            end\n            COUNT_LOOP: begin\n                if (i < num_beacons) begin\n                    if (!visited[i]) begin\n                        count <= count + 4'd1;\n                        visited <= visited | reach[i];\n                    end\n                    i <= i + 3'd1;\n                end else begin\n                    if (count > 4'd0) begin\n                        result <= count - 4'd1;\n                    end else begin\n                        result <= 4'd0;\n                    end\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n            end\n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule